from pydantic import BaseModel, Field
from enum import Enum
from typing import Dict, Union, Optional

class Unit(Enum):
    PERCENTAGE = "percentage"
    GEAR = "gear"
    CENTIMETER = "centimeter"

class SunshadeUnit(Unit):
    pass

class TrunkState(str, Enum):
    CLOSED = "closed"
    OPENING = "opening"
    OPEN = "open"
    CLOSING = "closing"
    PAUSED = "paused"

class WiperPosition(str, Enum):
    FRONT = "front"
    REAR = "rear"
    ALL = "all"

class SpeedUnit(Unit):
    pass

class Sunroof(BaseModel):
    value: Dict[str, Union[int, float]] = Field(
        {
            'open_degree_percentage': {'value': 0.0, 'description': 'Open degree in percentage'},
            'open_degree_gear': {'value': 0, 'description': 'Open degree in gears (0-10)'},
            'open_degree_centimeter': {'value': 0.0, 'description': 'Open degree in centimeters (0-50.0cm)'},
        },
        description='Sunroof'
    )
    configuration: Dict[str, Union[int, float]] = Field(
        {
            'max_gear': {'value': 10, 'description': 'Maximum number of gears'},
            'max_centimeter': {'value': 50.0, 'description': 'Maximum opening in centimeters'},
            'gear_to_percentage_ratio': {'value': 10.0, 'description': 'Gear to percentage ratio'},
            'centimeter_to_percentage_ratio': {'value': 2.0, 'description': 'Centimeter to percentage ratio'},
        },
        description='Sunroof configuration'
    )
    adjustment_values: Dict[str, Dict[str, Union[int, float]]] = Field(
        {
            'tiny': {'gear': 1, 'percentage': 10.0, 'centimeter': 5.0},
            'little': {'gear': 2, 'percentage': 20.0, 'centimeter': 10.0},
            'large': {'gear': 5, 'percentage': 50.0, 'centimeter': 25.0}
        },
        description='Adjustment increments for each degree level and unit'
    )
    open_degree_levels: Dict[str, float] = Field(
        {
            'min': 0.0,
            'low': 25.0,
            'medium': 50.0,
            'high': 75.0,
            'max': 100.0
        },
        description='Predefined percentage values for each open degree level'
    )


class Sunshade(BaseModel):
    front_row_status: Dict[str, Union[bool, float]] = Field(
        {'is_open': False, 'is_paused': False, 'open_degree_value': 0.0, 'open_degree_unit': Unit.PERCENTAGE},
        description='Status of the front row sunshade'
    )
    rear_row_status: Dict[str, Union[bool, float]] = Field(
        {'is_open': False, 'is_paused': False, 'open_degree_value': 0.0, 'open_degree_unit': Unit.PERCENTAGE},
        description='Status of the rear row sunshade'
    )
    leave_and_lock_auto_close_enabled: bool = Field(False, description='Auto-close when car is locked')


class TailLight(BaseModel):
    value: Dict[str, Union[bool]] = Field(
        {'is_on': False},
        description='Tail light switch status, True means on, False means off'
    )


class TrunkState(BaseModel):
    state: str = Field('closed', description='Current state of the trunk (closed, opening, open, closing, paused)')
    current_open_degree_percentage: float = Field(0.0, description='Current trunk open degree as percentage (0-100%)')
    current_open_degree_gear: int = Field(0, description='Current trunk open degree as gear level (0-10)')
    current_open_degree_cm: float = Field(0.0, description='Current trunk open height in centimeters (0-100.0)')
    max_open_height_cm: float = Field(100.0, description='Maximum trunk open height in centimeters')
    level_presets: Dict[str, float] = Field(
        {'min': 10.0, 'low': 25.0, 'medium': 50.0, 'high': 75.0, 'max': 100.0},
        description='Predefined trunk open degree levels as percentages'
    )
    adjustment_presets: Dict[str, float] = Field(
        {'tiny': 5.0, 'little': 10.0, 'large': 20.0},
        description='Predefined trunk open degree adjustment increments as percentages'
    )
    is_locked: bool = Field(True, description='Whether the trunk is locked (true) or unlocked (false)')
    is_in_motion: bool = Field(False, description='Whether the trunk is currently in motion')


class WiperState(BaseModel):
    front_wiper: Dict[str, Union[bool, float]] = Field(
        {'position': 'front', 'is_on': False, 'speed_setting': {'value': 1.0, 'unit': SpeedUnit.GEAR}},
        description='Front windshield wiper state'
    )
    rear_wiper: Dict[str, Union[bool, float]] = Field(
        {'position': 'rear', 'is_on': False, 'speed_setting': {'value': 1.0, 'unit': SpeedUnit.GEAR}},
        description='Rear windshield wiper state'
    )


class VehicleState(BaseModel):
    sunroof: Sunroof = Field(description='Sunroof system')
    sunshade: Sunshade = Field(description='Sunshade system')
    tailLight: TailLight = Field(description='Tail light system')
    trunk: TrunkState = Field(description='Trunk system')
    wiper: WiperState = Field(description='Wiper system')

